<?php
/** Admin view of unresolved dependencies for one game. */
declare(strict_types=1);
require_once __DIR__.'/lib/CatalogSupport.php';
require_once __DIR__.'/lib/BaseGameProtection.php';
use UnrealDb\Catalog\Infrastructure\Persistence\PdoGameMissingDependencyQuery;
catalog_start_session();
function game_missing_int(string $key,int $default=0):int{$v=filter_input(INPUT_GET,$key,FILTER_VALIDATE_INT);return$v===false||$v===null?$default:max(0,(int)$v);}
function game_missing_type():string{$v=strtolower(trim((string)($_GET['dependency_type']??'all')));return$v==='base_game'?'base_game':'all';}
function game_missing_url(int $gameId,string $type,array $params=[]):string{$q=array_merge(['game_id'=>$gameId,'dependency_type'=>$type],$params);$q=array_filter($q,static fn(mixed $v):bool=>$v!==null&&$v!==''&&$v!==0);return'game-missing.php?'.http_build_query($q);}
function game_missing_import_class(string $package,string $name):string{return implode('.',array_values(array_filter([$package,$name],static fn(string $v):bool=>trim($v)!=='')));}
try{
$config=catalog_config();$db=catalog_db($config);if(!catalog_require_admin_page('Game Missing Dependencies'))exit;base_game_ensure($db);
$games=catalog_all($db,'SELECT id,name,slug FROM ue_games ORDER BY name');$gameId=game_missing_int('game_id');$game=$gameId>0?catalog_one($db,'SELECT id,name,slug FROM ue_games WHERE id=?',[$gameId]):null;if(!$game)throw new RuntimeException('Choose a valid game from the Games page.');
$type=game_missing_type();$baseGameOnly=$type==='base_game';$selectedPackage=substr(trim((string)($_GET['package']??'')),0,255);if(session_status()===PHP_SESSION_ACTIVE)session_write_close();
$q=new PdoGameMissingDependencyQuery($db);$scope=$baseGameOnly?$q->officialBaseGamePackageNames($gameId):null;$totals=$q->totals($gameId,$scope);$missingObjects=(int)$totals['missing_objects'];$missingPackages=(int)$totals['missing_packages'];$filesWithMissing=(int)$totals['files_with_missing'];
$rows=$selectedPackage!==''?$q->detailRows($gameId,$selectedPackage,$scope,500,0):$q->missingRows($gameId,$scope,500,0);$packageRows=$q->packageRows($gameId,$scope,500,0);
$typeLabel=$baseGameOnly?'Official base-game dependencies only':'All missing dependencies';
catalog_head('Missing Dependencies — '.(string)$game['name']);
echo <<<'CSS'
<style>
.game-missing-filter{display:flex;align-items:end;gap:10px;flex-wrap:wrap}.game-missing-filter label{display:grid;gap:5px}.missing-summary{display:grid;grid-template-columns:repeat(3,minmax(180px,1fr));gap:12px;margin:16px 0}.missing-live-filter{display:flex;align-items:center;gap:10px;flex-wrap:wrap;margin:0 0 12px}.missing-live-filter input{width:min(520px,100%);min-width:240px}.missing-filter-count{white-space:nowrap}.missing-flow{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,.85fr) minmax(0,2fr);gap:0;align-items:stretch;width:100%}.missing-flow>div{min-width:0;padding:12px 14px;border-bottom:1px solid var(--border,#2b3950);overflow-wrap:anywhere;word-break:break-word;white-space:normal}.missing-flow__head{font-weight:700;background:rgba(255,255,255,.035)}.missing-flow-row{display:contents}.missing-flow-row.is-filtered{display:none}.missing-file strong,.missing-file a,.missing-package{display:block;min-width:0;max-width:100%;overflow-wrap:anywhere;word-break:break-word;white-space:normal}.missing-object{min-width:0;max-width:100%;overflow-wrap:anywhere;word-break:break-word;white-space:normal}.missing-class{display:block;margin-top:4px;overflow-wrap:anywhere;word-break:break-word;white-space:normal}.missing-package-summary{display:flex;gap:8px;flex-wrap:wrap}.missing-package-pill{display:inline-flex;gap:7px;align-items:center;min-width:0;max-width:100%;padding:7px 10px;border:1px solid var(--border,#2b3950);border-radius:8px;overflow-wrap:anywhere}.missing-package-pill strong{font-size:1.05em}.missing-package-extra{display:none}.missing-package-summary.is-expanded .missing-package-extra,.missing-package-summary.is-filtering .missing-package-extra{display:inline-flex}.missing-package-pill.is-filtered{display:none!important}.missing-package-more{margin-top:12px}.missing-package-more[hidden]{display:none}.missing-no-matches{display:none;margin:10px 0 0}.missing-no-matches.is-visible{display:block}@media(max-width:1000px){.missing-flow{grid-template-columns:minmax(0,.9fr) minmax(0,.75fr) minmax(0,1.35fr)}}@media(max-width:800px){.missing-summary{grid-template-columns:1fr}.missing-flow{grid-template-columns:1fr}.missing-flow__head{display:none}.missing-flow-row{display:block;border-bottom:1px solid var(--border,#2b3950)}.missing-flow-row.is-filtered{display:none}.missing-flow-row>div{border-bottom:0;padding-bottom:4px}.missing-flow-row>div:last-child{padding-bottom:12px}}
</style>
CSS;
echo CatalogUi::pageHeader('Missing Dependencies — '.(string)$game['name'],$typeLabel.'. Each unresolved object is shown with the file that requires it and the package/object path it expects.',['Games'=>'games.php','Global Missing Files'=>'missing.php','Game Files'=>'game-files.php?id='.$gameId]);
echo '<section class="ui-section"><div class="ui-section__header"><div><h2>Filter</h2></div></div><div class="ui-section__body"><form class="game-missing-filter" method="get"><label>Game<select name="game_id">';foreach($games as $candidate)echo '<option value="'.(int)$candidate['id'].'"'.((int)$candidate['id']===$gameId?' selected':'').'>'.catalog_h((string)$candidate['name']).'</option>';echo '</select></label><label>Dependency type<select name="dependency_type"><option value="all"'.(!$baseGameOnly?' selected':'').'>All missing dependencies</option><option value="base_game"'.($baseGameOnly?' selected':'').'>Official base-game dependencies only</option></select></label><button type="submit">Apply filters</button></form></div></section>';
echo '<div class="missing-summary">';catalog_stat_card('Missing objects',$missingObjects,'Individual object paths that could not be resolved',$missingObjects?'attention':'good');catalog_stat_card('Required packages',$missingPackages,'Packages containing those missing objects',$missingPackages?'attention':'good');catalog_stat_card('Affected files',$filesWithMissing,'Files that require one or more missing objects',$filesWithMissing?'attention':'good');echo '</div>';
if($packageRows!==[]){$packageTotal=count($packageRows);echo '<section class="ui-section"><div class="ui-section__header"><div><h2>At a glance</h2><p>Missing objects grouped by required package.</p></div></div><div class="ui-section__body"><div class="missing-live-filter"><input type="search" id="missing-package-filter" placeholder="Filter packages…" autocomplete="off" aria-label="Filter required packages"><span class="muted small missing-filter-count" id="missing-package-filter-count"></span></div><div class="missing-package-summary" id="missing-package-summary">';foreach($packageRows as $i=>$p){$name=(string)$p['required_package'];$extra=$i>=10?' missing-package-extra':'';echo '<a class="missing-package-pill'.$extra.'" data-filter-text="'.catalog_h(strtolower($name.' '.(int)$p['missing_object_rows'].' '.(int)$p['requiring_file_count'])).'" href="'.catalog_h(game_missing_url($gameId,$type,['package'=>$name])).'"><span class="mono">'.catalog_h($name).'</span><strong>'.(int)$p['missing_object_rows'].'</strong><span class="muted small">object'.((int)$p['missing_object_rows']===1?'':'s').' / '.(int)$p['requiring_file_count'].' file'.((int)$p['requiring_file_count']===1?'':'s').'</span></a>';}echo '</div><p class="muted missing-no-matches" id="missing-package-no-matches">No packages match this filter.</p>';if($packageTotal>10)echo '<button type="button" class="button secondary missing-package-more" id="missing-package-more" aria-expanded="false">Show '.($packageTotal-10).' more</button>';echo '</div></section>';}
$title=$selectedPackage!==''?'Missing objects in '.$selectedPackage:'Missing object paths';echo '<section class="ui-section"><div class="ui-section__header"><div><h2>'.catalog_h($title).'</h2><p>Read each row as: <strong>this file</strong> requires <strong>this package</strong> → <strong>this object path</strong>.</p></div>';if($selectedPackage!=='')echo '<a class="button secondary" href="'.catalog_h(game_missing_url($gameId,$type)).'">Show all missing objects</a>';echo '</div><div class="ui-section__body">';
if($rows===[]){echo CatalogUi::emptyState('No missing dependency objects','Nothing currently matches the selected game and dependency type.');}else{echo '<div class="missing-live-filter"><input type="search" id="missing-object-filter" placeholder="Filter files, packages, object paths or classes…" autocomplete="off" aria-label="Filter missing dependency objects"><span class="muted small missing-filter-count" id="missing-object-filter-count"></span></div><div class="missing-flow" id="missing-object-list"><div class="missing-flow__head">Requiring file</div><div class="missing-flow__head">Required package</div><div class="missing-flow__head">Missing object path</div>';foreach($rows as $r){$pkg=(string)($r['required_package']??$selectedPackage);$class=game_missing_import_class((string)($r['class_package']??''),(string)($r['class_name']??''));$filterText=strtolower(implode(' ',[(string)$r['owner_package_name'],(string)$r['owner_original_name'],$pkg,(string)$r['required_object_path'],$class]));echo '<div class="missing-flow-row" data-filter-text="'.catalog_h($filterText).'"><div class="missing-file"><strong class="mono"><a href="file-info.php?id='.(int)$r['file_id'].'">'.catalog_h((string)$r['owner_package_name']).'</a></strong><a class="muted small" href="file-examine.php?id='.(int)$r['file_id'].'">'.catalog_h((string)$r['owner_original_name']).'</a></div><div><a class="mono missing-package" href="'.catalog_h(game_missing_url($gameId,$type,['package'=>$pkg])).'">'.catalog_h($pkg).'</a></div><div class="mono missing-object">'.catalog_h((string)$r['required_object_path']).($class!==''?'<span class="muted small missing-class">Import class: '.catalog_h($class).'</span>':'').'</div></div>';}echo '</div><p class="muted missing-no-matches" id="missing-object-no-matches">No missing objects match this filter.</p>';}
echo '</div></section>';
echo '<script>(function(){function norm(v){return (v||"").toLocaleLowerCase().trim();}const packageList=document.getElementById("missing-package-summary"),packageInput=document.getElementById("missing-package-filter"),packageButton=document.getElementById("missing-package-more"),packageCount=document.getElementById("missing-package-filter-count"),packageEmpty=document.getElementById("missing-package-no-matches");if(packageList&&packageInput){const pills=Array.from(packageList.querySelectorAll(".missing-package-pill"));function filterPackages(){const q=norm(packageInput.value);packageList.classList.toggle("is-filtering",q!=="");let matches=0;pills.forEach(function(pill){const hit=q===""||norm(pill.dataset.filterText).includes(q);pill.classList.toggle("is-filtered",!hit);if(hit)matches++;});if(packageCount)packageCount.textContent=q!==""?matches+" of "+pills.length+" packages":"";if(packageEmpty)packageEmpty.classList.toggle("is-visible",q!==""&&matches===0);if(packageButton)packageButton.hidden=q!=="";}packageInput.addEventListener("input",filterPackages);if(packageButton)packageButton.addEventListener("click",function(){const expanded=packageList.classList.toggle("is-expanded");packageButton.setAttribute("aria-expanded",expanded?"true":"false");packageButton.textContent=expanded?"Show less":"Show "+Math.max(0,pills.length-10)+" more";});}const objectList=document.getElementById("missing-object-list"),objectInput=document.getElementById("missing-object-filter"),objectCount=document.getElementById("missing-object-filter-count"),objectEmpty=document.getElementById("missing-object-no-matches");if(objectList&&objectInput){const rows=Array.from(objectList.querySelectorAll(".missing-flow-row"));function filterObjects(){const q=norm(objectInput.value);let matches=0;rows.forEach(function(row){const hit=q===""||norm(row.dataset.filterText).includes(q);row.classList.toggle("is-filtered",!hit);if(hit)matches++;});if(objectCount)objectCount.textContent=q!==""?matches+" of "+rows.length+" objects":"";if(objectEmpty)objectEmpty.classList.toggle("is-visible",q!==""&&matches===0);}objectInput.addEventListener("input",filterObjects);}})();</script>';
catalog_foot();
}catch(Throwable $error){if(!headers_sent())catalog_head('Game missing dependencies error');echo CatalogUi::alert('danger',$error->getMessage(),'The filtered missing-dependency page could not be loaded.');catalog_foot();}
